// src/daily.js





function eligibleDaily(s,kind) {
  return (ageOf(s)<=11 ? childhoodEvents : dailyEvents).filter(e=>e.kind===kind && matches(s,e.when) && !(atFront(s) && (e.when.places || e.when.placeIncludes)) && !(isAbroad(s) && (e.when.places || e.when.placeIncludes || e.when.notPlaceIncludes || e.when.classes)) && !(e.when.parentJobs && ageOf(s) >= 14 && !e.when.parentJobs.some(p => (s.job || '').includes(p))) && (e.repeatable!==false || !s.seenEvents?.includes(e.id)));
}
function selectDaily(s,kind) {
  const pool=eligibleDaily(s,kind);
  const groups=['universal','personal','historical'].map(category=>({category,weight:category==='historical'?20:category==='personal'?55:25,events:pool.filter(e=>(e.category||'universal')===category)})).filter(g=>g.events.length);
  let roll=random(s)*groups.reduce((n,g)=>n+g.weight,0);
  const group=personalFirst(s,groups,groups.find(g=>(roll-=g.weight)<0)||groups.at(-1));
  if(!group)return null;
  const override=group.events.find(e=>e.overrideChance!==undefined&&random(s)<e.overrideChance);
  if(override)return override;
  return pick(s,preferFresh(s,group.events.filter(e=>e.overrideChance===undefined).length ? group.events.filter(e=>e.overrideChance===undefined) : group.events));
}
function learningOpportunity(s) {
  const burden = s.paths.learning==='family' && s.paths.priority!=='study' ? .4 : 1;
  return Math.min(.8,.25+(s.experience?.educationInterest||0)*.04+(s.stats.재산>=55?.15:0))*burden*girlsLearningFactor(s);
}
function informalLearningOpportunity(s) {
  return (s.paths.learning==='family' && s.paths.priority!=='study' ? .08 : .24) * girlsLearningFactor(s);
}
function decisionDomain(d) { return DECISION_DOMAINS.find(domain=>domain.id===d.domain)?.label || '삶'; }
function decisionContext(s) {
  const family = ['인쇄공','직물공','제화공','장인'].includes(s.parentJob) ? '장인 가정' : `${s.class} 가정`;
  return `${s.year}년 · ${ageOf(s)}세 · ${s.place} · ${family}`;
}
function decisionText(s,d) {
  if (d.id !== 'school') return bondFill(s, d, voiceText(s, d));
  if (d.id!=='school') return d.text;
  if (!s.relations.some(r=>r.role==='아버지'&&r.alive) || !s.relations.some(r=>r.role==='어머니'&&r.alive))
    return '이웃집 아이가 교구의 자선학교에 다니기 시작했습니다. 당신도 글을 배우고 싶지만, 집안의 생계에도 일손이 필요합니다. 가족과 배움의 기회를 의논할 때입니다.';
  return literacyOf(s)==='illiterate' ? d.text : d.text.replace('당신도 글을 배우고 싶지만','당신도 글을 더 배우고 싶지만');
}
function outcomeFor(choice,id) {
  return choice.outcomes ? choice.outcomes.find(outcome=>outcome.id===id)
    : id==='default' ? {id:'default',title:'선택의 결과',result:choice.result,effects:{}} : null;
}
function resolveOutcome(s,choice) {
  if (!choice.outcomes) return outcomeFor(choice,'default');
  if (choice.outcomes.length===1) return choice.outcomes[0];
  // Weights are game design values, not reconstructed historical probabilities.
  const weighted=choice.outcomes.map(outcome=>({outcome,weight:Math.max(1,(outcome.weight||1)+(outcome.modifiers||[]).filter(m=>matches(s,m.when)).reduce((n,m)=>n+m.amount,0))}));
  let roll=random(s)*weighted.reduce((n,item)=>n+item.weight,0);
  return (weighted.find(item=>(roll-=item.weight)<0)||weighted.at(-1)).outcome;
}

// src/focus.js
// The player's standing focus for the year ("올해의 초점"). Applied once a year, deterministic: no RNG.
const FOCUS_OPTIONS = {
  child:[{id:'play',label:'뛰어놀기'},{id:'family',label:'가족 곁에서'},{id:'explore',label:'동네 구경'}],
  school:[{id:'chores',label:'집안 돕기'},{id:'study',label:'글 배우기'},{id:'play',label:'친구와 놀기'},{id:'faith',label:'교리 공부'}],
  youth:[{id:'craft',label:'기술 익히기'},{id:'work',label:'돈 벌기'},{id:'study',label:'공부'},{id:'social',label:'친구·연애'},{id:'rest',label:'쉬기'}],
  adult:[{id:'work',label:'생업에 전념'},{id:'family',label:'가족 돌보기'},{id:'save',label:'아껴 모으기'},{id:'social',label:'이웃과 교류'},{id:'study',label:'배움·독서'},{id:'rest',label:'몸 돌보기'}],
  elder:[{id:'rest',label:'몸 돌보기'},{id:'family',label:'가족 곁에서'},{id:'faith',label:'신앙생활'},{id:'social',label:'옛 친구 만나기'}]
};
const FOCUS_EFFECTS = {
  play:{stats:{행복:2,건강:1},experience:{social:1},hint:'행복과 건강이 조금씩 오릅니다.'},
  family:{stats:{행복:1},closeness:1,experience:{responsibility:1},hint:'가족과의 친밀도가 오릅니다.'},
  explore:{stats:{행복:1},experience:{curiosity:1},hint:'호기심이 자랍니다.'},
  chores:{stats:{재산:1},closenessRoles:['아버지','어머니'],experience:{familyTrade:1,responsibility:1},hint:'가업에 익숙해지고 부모와 가까워집니다.'},
  study:{stats:{지식:2,행복:-1},experience:{educationInterest:1,selfStudy:1},hint:'지식이 오르지만 놀 시간이 줄어듭니다.'},
  faith:{stats:{행복:1},experience:{religious:1},hint:'교구 공동체와 가까워집니다.'},
  craft:{stats:{지식:1,재산:1},experience:{craft:1},hint:'손기술과 수입이 조금씩 늘어납니다.'},
  work:{stats:{재산:2,행복:-1},experience:{responsibility:1},hint:'벌이는 늘지만 여유가 줄어듭니다.'},
  social:{stats:{행복:1},friends:2,experience:{social:1},hint:'친구·이웃과 가까워집니다.'},
  rest:{stats:{건강:2,재산:-1},hint:'건강을 회복하지만 벌이가 줄어듭니다.'},
  save:{stats:{재산:1,행복:-1},experience:{commerce:1},hint:'조금씩 모으지만 생활이 빠듯합니다.'}
};
const FOCUS_IDS = new Set(Object.values(FOCUS_OPTIONS).flat().map(f => f.id));
function focusStage(s) { const a = ageOf(s); return a < 2 ? null : a < 7 ? 'child' : a < 14 ? 'school' : a < 20 ? 'youth' : a < 60 ? 'adult' : 'elder'; }
function focusOptions(s) { const st = focusStage(s); return st ? FOCUS_OPTIONS[st] : []; }
function currentFocus(s) { const opts = focusOptions(s); return opts.find(f => f.id === s.focus) || opts[0] || null; }
function applyFocus(s) {
  const f = currentFocus(s); if (!f) return;
  const e = FOCUS_EFFECTS[f.id];
  changeStats(s, e.stats);
  s.experience ??= emptyExperience();
  for (const [k,v] of Object.entries(e.experience || {})) s.experience[k] = clamp((s.experience[k] || 0) + v);
  for (const r of s.relations) {
    if (!r.alive) continue;
    if (e.closeness) r.closeness = clamp(r.closeness + e.closeness);
    if (e.closenessRoles?.includes(r.role)) r.closeness = clamp(r.closeness + 2);
    if (e.friends && r.role === '친구') r.closeness = clamp(r.closeness + e.friends);
  }
  if (f.id === 'study' && s.literacy === 'learning' && s.stats.지식 >= 20) s.literacy = 'basic';
}
// Shown as the fifth stat. Derived, never saved.
function relationScore(s) {
  const alive = s.relations.filter(r => r.alive);
  return alive.length ? Math.round(alive.reduce((n,r) => n + r.closeness, 0) / alive.length) : 0;
}

// src/facts.js
// Birthday notes about the era, in the manner of "N명 중 1명은...". These are rounded, commonly cited
// demographic approximations for France, not outputs of this game's simplified mortality model.
function eraFact(s, age) {
  const early = s.born < 1790, man = s.sex === '남성';
  if (age === 1) return early
    ? '이 시대 프랑스에서는 아기 넷 중 한 명꼴로 첫돌을 넘기지 못했습니다. 당신은 첫돌을 맞이했습니다.'
    : '19세기 초 프랑스에서도 아기 다섯 중 한 명꼴로 첫돌을 넘기지 못했습니다. 당신은 첫돌을 맞이했습니다.';
  if (age === 10) return early
    ? '같은 해에 태어난 프랑스 아이의 절반 가까이가 열 살이 되기 전에 세상을 떠났습니다. 당신은 열 번째 생일을 맞았습니다.'
    : '같은 해에 태어난 아이 셋 중 한 명꼴이 열 살이 되기 전에 세상을 떠났습니다. 당신은 열 번째 생일을 맞았습니다.';
  if (age === 16) {
    const late = s.year >= 1810, rate = man ? (late ? 54 : 47) : (late ? 34 : 27);
    const you = literacyOf(s) === 'basic' ? '당신은 글을 읽고 쓸 수 있습니다.' : literacyOf(s) === 'learning' ? '당신은 아직 글을 배우는 중입니다.' : '당신은 아직 글을 읽지 못합니다.';
    return `이 무렵 프랑스 ${man ? '남성' : '여성'} 가운데 혼인 서약서에 자기 이름을 서명할 수 있는 사람은 약 ${rate}%였습니다. ${you}`;
  }
  if (age === 26) {
    const married = s.relations.some(r => r.role === '배우자');
    return `이 시대 프랑스인의 첫 결혼은 늦은 편이어서, 평균 남성 약 28세·여성 약 26세에 혼인했습니다. ${married ? '당신은 이미 가정을 꾸렸습니다.' : '당신은 아직 혼인하지 않았습니다.'}`;
  }
  if (age === 40) return '이 시대 프랑스인의 출생 시 기대수명은 30년 안팎이었습니다. 어린 시절의 높은 사망률이 평균을 끌어내린 결과로, 어른이 된 사람은 대개 그보다 오래 살았습니다.';
  if (age === 60) return '같은 해에 태어난 사람 가운데 예순 살 생일을 맞는 사람은 넷 중 한 명 남짓이었습니다.';
  if (age === 75) return '일흔다섯 살. 같은 해에 태어난 사람 대부분은 이미 세상을 떠났습니다.';
  return null;
}
function birthdayFacts(s) {
  if (s.dead || s.month !== s.birthMonth) return;
  const age = ageOf(s), key = 'fact-' + age;
  if (s.familyEvents[key]) return;
  const text = eraFact(s, age);
  if (!text) return;
  s.familyEvents[key] = true;
  addLog(s, '시대의 숫자', text, 'fact');
}

// src/mortality.js
// Births and deaths in the household, and the player's own bad luck. A game model with rates
// rounded from French historical demography; not a reconstruction of any real family.
const monthIndex = (year, month) => year*12 + month;
function monthsOld(s, r) { return monthIndex(s.year, s.month) - monthIndex(r.birthYear, r.birthMonth || 1); }
function siblingWord(s, r) {
  const sex = personSex(r), older = monthIndex(r.birthYear, r.birthMonth || 1) < monthIndex(s.born, s.birthMonth);
  if (!older) return sex === '여성' ? '여동생' : '남동생';
  if (s.sex === '남성') return sex === '여성' ? '누나' : '형';
  return sex === '여성' ? '언니' : '오빠';
}
// A name nobody else in the living family already uses.
function freshName(s, list, surname) {
  const used = new Set([s.name, ...s.relations.filter(r => r.alive).map(r => r.name)].map(n => n.split(' ')[0]));
  const options = list.filter(n => !used.has(n));
  return pick(s, options.length ? options : list) + ' ' + surname;
}
function infantMonthlyRisk(s, birthYear) { return birthYear < 1800 ? .023 : .018; }

function familyMonth(s) {
  if (s.dead) return;
  const surname = s.name.split(' ').at(-1);
  const mother = s.relations.find(r => r.role === '어머니' && r.alive), father = s.relations.find(r => r.role === '아버지' && r.alive);
  // Younger siblings keep arriving while the parents are together and the mother is of age.
  if (mother && father && ageOf(s) < 20) {
    const births = [monthIndex(s.born, s.birthMonth), ...s.relations.filter(r => r.role === '형제자매').map(r => monthIndex(r.birthYear, r.birthMonth || 1))];
    const gap = monthIndex(s.year, s.month) - Math.max(...births), motherAge = ageOf(s, mother);
    if (motherAge >= 18 && motherAge <= 42 && births.length < 8 && gap >= 15 && random(s) < .03) {
      const sex = pick(s, ['남성','여성']);
      const r = {name:freshName(s, sex === '남성' ? male : female, surname), role:'형제자매', sex, birthYear:s.year, birthMonth:s.month,
        alive:true, closeness:rand(s, 55, 80), job:'없음'};
      s.relations.push(r);
      addLog(s, '가족의 변화', `${siblingWord(s, r)} ${r.name}이(가) 태어났습니다.`, 'good');
      changeStats(s, {행복:3});
    }
  }
  // Infant and child mortality for siblings and the player's own children.
  for (const r of s.relations) {
    if (!r.alive || !['형제자매','자녀'].includes(r.role)) continue;
    const m = monthsOld(s, r);
    if (m <= 0) continue;
    const q = (m < 12 ? infantMonthlyRisk(s, r.birthYear) : m < 60 ? .003 : m < 120 ? .0009 : 0) * crisisFactor(s);
    if (!q || random(s) >= q) continue;
    r.alive = false; r.deathYear = s.year;
    const who = r.role === '자녀' ? `${personSex(r) === '여성' ? '딸' : '아들'} ${r.name}` : `${siblingWord(s, r)} ${r.name}`;
    const text = m < 12 ? `갓 태어난 ${who}이(가) 첫돌을 넘기지 못하고 세상을 떠났습니다.`
      : `${who}이(가) ${Math.floor(m/12)}살의 어린 나이에 병으로 세상을 떠났습니다.`;
    addLog(s, '가족의 슬픔', text, 'bad');
    milestone(s, `${who}과(와) 작별`);
    changeStats(s, {행복: r.role === '자녀' ? -15 : -8});
    if (r.role === '자녀') s.relations.forEach(p => { if (p.role === '배우자' && p.alive) p.closeness = clamp(p.closeness + 3); });
  }
}

// The player's own risk, rolled once a year. Poor health and poverty raise every risk.
function fateYear(s) {
  if (s.dead) return;
  const age = ageOf(s), h = s.stats.건강, job = s.job || '';
  // Poverty raises every risk and wealth lowers it a little; hunger years make poverty worse.
  const w = s.stats.재산, wealthRisk = w < 15 ? 1.4 : w < 30 ? 1.15 : w >= 70 ? .85 : 1;
  const frail = (h < 25 ? 3 : h < 45 ? 1.8 : 1) * wealthRisk * crisisFactor(s);
  const risks = [];
  if (age < 5) risks.push([.006, '어린 시절 열병을 이겨 내지 못했습니다.']);
  else if (age < 15) risks.push(smallpoxImmune(s) ? [.0017, '이질에 걸려 끝내 회복하지 못했습니다.'] : [.002, '천연두에 걸려 끝내 회복하지 못했습니다.']);
  else risks.push([.003 + Math.max(0, age - 40)*.0005, '갑작스러운 병으로 세상을 떠났습니다.']);
  if (age >= 14 && /노동|농|직물|인쇄|제화|도제|장인|보조/.test(job)) risks.push([.0015, '작업 중 사고를 당해 목숨을 잃었습니다.']);
  const war = (s.year >= 1792 && s.year <= 1815) || (s.year >= 1756 && s.year <= 1763);
  if (war && /군/.test(job) && age >= 16 && age <= 50) risks.push([.035, '전장에서 돌아오지 못했습니다.']);
  if (s.year === 1832 && s.place.includes('파리')) risks.push([.012, '1832년 콜레라에 걸려 세상을 떠났습니다.']);
  if (s.year === 1849 && s.place.includes('파리')) risks.push([.006, '콜레라에 걸려 세상을 떠났습니다.']);
  for (const [p, reason] of risks) if (random(s) < p * frail) { endLife(s, reason); return; }
}

// Childbirth was dangerous for the mother: roughly one birth in a hundred.
function childbirthRisk(s) {
  if (s.sex === '여성') { if (random(s) < .012) endLife(s, '출산 뒤 회복하지 못했습니다.'); return; }
  const wife = s.relations.find(r => r.role === '배우자' && r.alive);
  if (wife && random(s) < .012) {
    wife.alive = false; wife.deathYear = s.year;
    addLog(s, '가족의 슬픔', `배우자 ${wife.name}이(가) 출산 뒤 회복하지 못하고 세상을 떠났습니다.`, 'bad');
    milestone(s, `배우자 ${wife.name}과 작별`); changeStats(s, {행복:-18});
  }
}

// Some families had already lost a child before the player was born.
function earlierLoss(s) {
  if (random(s) >= .35) return;
  const sex = pick(s, ['남성','여성']), birthYear = s.born - rand(s, 1, 4), months = rand(s, 1, 11);
  const r = {name:freshName(s, sex === '남성' ? male : female, s.name.split(' ').at(-1)), role:'형제자매', sex, birthYear, birthMonth:rand(s, 1, 12),
    alive:false, closeness:50, job:'없음'};
  r.deathYear = Math.min(s.born, birthYear + (r.birthMonth + months > 12 ? 1 : 0));
  s.relations.push(r);
  addLog(s, '가족의 기억', `당신이 태어나기 전, ${siblingWord(s, r)} ${r.name}은(는) 첫돌을 넘기지 못하고 세상을 떠났습니다.`, 'normal');
}

// Softer bad luck: bad everyday events and the original decisions cost less health.
// Runs before the era decisions are added, so only the original data is rescaled.
for (const e of [...dailyEvents, ...childhoodEvents]) {
  const h = e.effects?.stats?.건강;
  if (e.kind === 'bad' && h < 0) e.effects.stats.건강 = Math.trunc(h * 0.4) || -1;
}
for (const d of decisions) for (const c of d.choices) {
  const h = c.effects?.stats?.건강;
  if (h < -1) c.effects.stats.건강 = Math.trunc(h / 2);
}
// The yearly focus replaced these two filler decisions; the rest of the repeatable ones are rationed.
const RETIRED_DECISIONS = new Set(['childcare','livelihood']);
function decisionAllowed(s, d) {
  if (typeof realBlocks === 'function' && realBlocks(s, d)) return false;
  if (typeof lifeFixBlocks === 'function' && lifeFixBlocks(s, d)) return false;
  // Abroad, home-town decisions and the ordinary career ladder wait.
  if (typeof isAbroad === 'function' && isAbroad(s) && !d.historic && (d.domain === 'career' || d.domain === 'housing' || d.when.places || d.when.placeIncludes || d.when.notPlaces || d.when.notPlaceIncludes)) return false;
  if (RETIRED_DECISIONS.has(d.id)) return false;
  // One-off decisions gated on a shared flag (e.g. 'marriage') also close on their own id.
  if (d.when.unsetFlag && d.when.unsetFlag !== d.id && s.flags[d.id]) return false;
  if (d.when.unsetFlag) return true;
  const n = s.familyEvents['dc-' + d.id] || 0, y = s.familyEvents['dy-' + d.id];
  return n < 2 && (y === undefined || s.year - y >= 7);
}
function noteDecision(s, d) {
  s.familyEvents['t-' + d.id] = s.year;  // when it was decided, for decisions that follow up years later
  if (d.when.unsetFlag) return;
  s.familyEvents['dc-' + d.id] = (s.familyEvents['dc-' + d.id] || 0) + 1;
  s.familyEvents['dy-' + d.id] = s.year;
}

// Inoculation (variolation) and vaccination both gave lasting protection; a child who had either cannot
// die of smallpox later. Read from the decision log, so saves made before this rule are covered too.
function smallpoxImmune(s) {
  return s.log.some(x => (x.eventId === 'inoculation' && x.desc.includes('선택: 부모가 접종을 받게 한다'))
    || (x.eventId === 'vaccine' && x.desc.includes('선택: 접종을 받는다')));
}

