// src/groups.js — 사건 분류: 공통 · 신분별 · 직업별 · 관계
// Every everyday event and decision falls into one of four groups, read from its conditions:
//   관계   — about family, spouse, children, parents, friends (relationship roles, family domains)
//   직업별 — tied to the work you do (job or career conditions, the career domain)
//   신분별 — tied to your estate or class (class conditions)
//   공통   — anyone of the time and place may meet it
// Historic scenes keep their own label (역사의 현장) but are grouped the same way underneath.
const EVENT_GROUPS = {common:'공통', class:'신분별', job:'직업별', relation:'관계'};
function eventGroup(e) {
  const w = e.when || {};
  if (w.livingRoles || w.livingRolesAny || w.childAge || w.parentAgeMin || w.hasChild || w.hadRoles || w.noLivingRoles || w.bond
    || ['marriage', 'family', 'parenting', 'relationships', 'bond'].includes(e.domain) || e.effects?.relationCloseness) return 'relation';
  if (w.jobMatch || w.hasJob || w.careerIs || w.minRank !== undefined || w.noCareer || e.domain === 'career') return 'job';
  if (w.classes || w.royalOfficer) return 'class';
  return 'common';
}
let EVENT_GROUP_INDEX = null;
function eventGroupOf(id) {
  if (!EVENT_GROUP_INDEX) {
    EVENT_GROUP_INDEX = new Map();
    for (const e of [...childhoodEvents, ...dailyEvents, ...decisions]) if (!EVENT_GROUP_INDEX.has(e.id)) EVENT_GROUP_INDEX.set(e.id, eventGroup(e));
  }
  return EVENT_GROUP_INDEX.get(id) || null;
}

// src/engine.js










function findDecision(s) {
  const school = decisions.find(d=>d.id==='school');
  const schoolContext = matches(s,{...school.when,minAge:6}) && s.paths.learning!=='study';
  const candidates = decisions.filter(d => !d.historic && decisionAllowed(s, d) && matches(s, d.when) && (d.chance === undefined || random(s) < d.chance)
    && (d.id!=='school' || s.paths.learning!=='study')
    && (d.id!=='learn' || (!schoolContext && !s.flags.school && literacyOf(s)!=='basic' && random(s)<learningOpportunity(s))));
  if (!candidates.length) return null;
  const priority = Math.max(...candidates.map(d => d.priority || 0));
  return pick(s, candidates.filter(d => (d.priority || 0) === priority));
}
function historyMonth(s) {
  for (const event of historicalEvents) {
    if (event.year !== s.year || event.month !== s.month || s.processedHistory.includes(event.id)) continue;
    const impacts = (event.impacts || []).filter(i => matches(s, i.when));
    for (const impact of impacts) changeStats(s, impact.stats);
    addLog(s, '역사적 사건', [event.text, ...impacts.map(i => i.text)].join('\n'), 'history', event.id);
    politicalMood(s, event);
    s.processedHistory.push(event.id);
    checkHealth(s);
    if (s.dead) return;
  }
}
function dailyEvent(s) {
  if (s.dead || (s.yearEvents[s.year]||0)>=3) return;
  const r = random(s), kind = r < .29 ? 'good' : r < .69 ? 'normal' : 'bad';
  const event = selectDaily(s,kind);
  if(!event)return;
  applyEffects(s, event.effects);
  remember(s,event);
  s.dailyCategories ??= {universal:0,personal:0,historical:0};
  s.dailyCategories[event.category||'universal']++;
  s.yearEvents[s.year] = (s.yearEvents[s.year] || 0) + 1; s.eventTally[kind]++;
  addLog(s, ({good:'🌿 좋은 일',normal:'☕ 일상',bad:'🌧️ 나쁜 일'})[kind] + ' · ' + event.title, event.text, kind, event.id);
  checkHealth(s);
  if (s.dead) return;
  if (s.month === 7 && random(s) < .18) {
    const friends = s.relations.filter(p => p.role === '친구' && p.alive);
    if (friends.length) {
      const friend = pick(s, friends); friend.closeness = clamp(friend.closeness + rand(s,-5,8));
      addLog(s, '인간관계', `${friend.name}과(와) 시간을 보내며 근황을 나누었습니다.`);
    }
  }
  if (ageOf(s) >= 16 && s.month === 11 && random(s) < .08) changeStats(s, {재산:rand(s,-3,6)});
}
function annual(s) {
  s.yearEvents[s.year] = 0;
  changeStats(s, {건강: ageOf(s) < 40 ? rand(s,-1,1) : rand(s,-2,1)});
  if (ageOf(s) > 10 && !['없음','은퇴'].includes(s.job)) changeStats(s, {재산:rand(s,-1,2)});
  checkHealth(s);
  if (s.dead) return;
  yearlyPaths(s); applyFocus(s); knowledgeYear(s); familyYear(s); careerYear(s); armyYear(s); bondYear(s); kinMarry(s); lifeFixYear(s); crisisYear(s); fateYear(s);
  if (s.dead) return;
  const gap = s.year - s.lastDecision;
  if (ageOf(s) >= 2 && gap >= 1 && (gap >= 2 || random(s) < .66)) s.pendingDecisionYear = s.year;
}

// The engine owns state transitions. It has no DOM, storage, or animation callbacks.
class GameEngine {
  constructor(state = null) { this.state = state; }
  replace(state) { this.state = state; }
  advanceMonth() {
    const s = this.state;
    if (!s || s.dead || s.decision || s.runtime.paused) return false;
    s.month++;
    if (s.month > 12) { s.month = 1; s.year++; annual(s); }
    if (s.dead) return true;
    historyMonth(s);
    if (s.dead) return true;
    birthdayFacts(s);
    familyMonth(s);
    if (s.dead) return true;
    figureFates(s);
    realKeep(s);
    historicDecision(s);
    if (s.decision) return true;
    if ([3,7,11].includes(s.month)) dailyEvent(s);
    if (s.dead) return true;
    if (s.year === s.born+2 && s.month === s.birthMonth && s.lastDecision < s.born) {
      const d = findDecision(s);
      s.decision = d.id; s.lastDecision = s.year; s.pendingDecisionYear = null;
      return true;
    }
    if (s.month === 6 && s.pendingDecisionYear === s.year) {
      s.pendingDecisionYear = null;
      const d = findDecision(s);
      if (d) { s.decision = d.id; s.lastDecision = s.year; }
    }
    return true;
  }
  advanceRealTime(ms) {
    const s = this.state;
    if (!s || s.dead || s.decision || s.runtime.paused || !Number.isFinite(ms) || ms <= 0) return false;
    s.runtime.monthProgress += ms / (4000 / s.runtime.speed);
    let changed = false;
    while (s.runtime.monthProgress >= 1 - 1e-9 && !s.dead && !s.decision) {
      s.runtime.monthProgress = Math.max(0,s.runtime.monthProgress - 1); this.advanceMonth(); changed = true;
    }
    // Do not bank elapsed time from after a decision or death for a later jump.
    if (s.decision || s.dead) s.runtime.monthProgress = 0;
    return changed;
  }
  choose(index) {
    const s = this.state, d = decisions.find(x => x.id === s?.decision);
    if (!s || s.dead || !d || s.decisionResult || !Number.isInteger(index) || !d.choices[index] || !choiceAvailable(s, d.choices[index])) return false;
    const choice = d.choices[index], outcome = resolveOutcome(s,choice), statsBefore = {...s.stats};
    applyEffects(s, choice.effects);
    applyEffects(s, outcome.effects);
    remember(s,d); noteDecision(s,d);
    addLog(s, `중대 결정 · ${decisionDomain(d)} · ${d.title}`, `${decisionContext(s)}\n선택: ${bondFill(s, d, choice.label)}\n결과: ${outcome.title}\n${bondFill(s, d, outcome.result)}`, 'major', d.id);
    s.decisionResult = {choiceIndex:index,outcomeId:outcome.id,statsBefore};
    s.runtime.monthProgress=0;
    checkHealth(s);
    return true;
  }
  acknowledgeDecision() {
    const s=this.state;
    if (!s || s.dead || !s.decision || !s.decisionResult) return false;
    s.decision=null; s.decisionResult=null;
    if (s.familyEvents.doom) { const reason = s.familyEvents.doom; delete s.familyEvents.doom; endLife(s, reason); }
    return true;
  }
  setFocus(id) {
    const s = this.state;
    if (!s || s.dead || !focusOptions(s).some(f => f.id === id)) return false;
    s.focus = id; return true;
  }
  toggleStar(index) {
    const entry = this.state?.log[index];
    if (!entry) return false;
    if (entry.star) delete entry.star; else entry.star = true;
    return true;
  }
  // Runs months synchronously until a decision opens or the life ends.
  skipToDecision(maxMonths = 600) {
    const s = this.state;
    if (!s || s.dead || s.decision) return false;
    const paused = s.runtime.paused;
    s.runtime.paused = false; s.runtime.monthProgress = 0;
    let months = 0;
    while (months < maxMonths && !s.dead && !s.decision) { this.advanceMonth(); months++; }
    if (!s.dead) s.runtime.paused = paused;
    return months;
  }
  setSpeed(speed) {
    if (!this.state || !SPEEDS.includes(speed)) return false;
    this.state.runtime.speed = speed; return true;
  }
  togglePause() {
    if (!this.state || this.state.dead || this.state.decision) return false;
    this.state.runtime.paused = !this.state.runtime.paused; return true;
  }
}

// src/clock.js
// Single RAF loop. Visibility changes reset the baseline; background time is not simulated.
class GameClock {
  constructor(engine, {request = callback => globalThis.requestAnimationFrame(callback),
    cancel = handle => globalThis.cancelAnimationFrame(handle),
    onChange = () => {}, onFrame = () => {}, maxDelta = 250} = {}) {
    this.engine = engine; this.request = request; this.cancel = cancel;
    this.onChange = onChange; this.maxDelta = maxDelta;
    this.onFrame = onFrame;
    this.handle = null; this.last = null; this.active = false;
    this.frame = now => {
      this.handle = null;
      if (!this.active) return;
      const delta = this.last === null ? 0 : Math.max(0, Math.min(this.maxDelta, now - this.last));
      this.last = now;
      if (this.engine.advanceRealTime(delta)) this.onChange();
      this.onFrame();
      if (this.active) this.handle = this.request(this.frame);
    };
  }
  start() {
    if (this.active) return;
    this.active = true; this.last = null; this.handle = this.request(this.frame);
  }
  reset() { this.last = null; }
  stop() {
    this.active = false;
    if (this.handle !== null) this.cancel(this.handle);
    this.handle = null; this.last = null;
  }
}

