function lifeFocus(s) {
  const age = ageOf(s);
  if (s.dead) return {title:'한 사람의 삶이 남았습니다',text:'기록과 이정표를 돌아보며 지나온 선택과 인연을 살펴보세요.'};
  if (age < 2) return {title:'품 안에서 시작된 삶',text:`${s.place}의 집 안에서 세상을 처음 만납니다. 아직은 가까운 어른의 보살핌이 하루의 대부분을 채웁니다.`};
  if (age < 7) return {title:'조금씩 넓어지는 세상',text:'익숙한 얼굴과 목소리를 알아가고, 놀이 속에서 주변을 배웁니다. 작은 반응과 만남이 가족과의 관계에 남습니다.'};
  if (age < 14) return {title:'배움과 집안일 사이',text:`${s.education === '미정' ? '배움의 기회를 기다리며' : s.education+'을 이어 가며'} 가족의 생활을 알아갑니다. 가정의 형편과 주변의 도움이 앞으로의 길에 영향을 줍니다.`};
  if (age < 20) return {title:'나의 생업을 찾아서',text:`${s.job === '없음' ? '어떤 일을 배울 수 있을지 살피고 있습니다.' : s.job+'로 생활에 필요한 경험을 쌓습니다.'} 익숙한 곳에 남을지 새로운 기회를 찾을지 생각할 때입니다.`};
  if (age < 55) return {title:'일과 사람들로 채워지는 날들',text:`${s.place}에서 ${s.job === '없음' ? '생계를 꾸릴 방법을 살피며' : s.job+'의 일상을 보내며'} 가까운 이들과 관계를 이어 갑니다. 시대의 변화가 개인의 생활에도 닿습니다.`};
  return {title:'쌓인 세월, 달라지는 일상',text:'몸의 변화에 맞추어 일을 조정하고, 곁에 남은 사람들과 시간을 나눕니다. 지나온 선택의 흔적이 오늘의 생활에 남아 있습니다.'};
}
function birthdayProgress(s) {
  if (s.dead) return 0;
  return (((s.month-s.birthMonth+12)%12)+s.runtime.monthProgress)/12;
}

